KUMITE_BILINGUAL: dict[int, dict[str, str]] = {
    1: {"en": "Any voluntary religious headwear can be worn.", "vi": "Bất kỳ khăn trùm đầu tôn giáo tự nguyện nào cũng có thể được đeo."},
    2: {"en": "The Karate Gi jacket must be more than three-quarters thigh length.", "vi": "Áo võ phục Karate Gi phải dài hơn ba phần tư chiều dài đùi."},
    3: {"en": "The Karate Gi trousers must cover at least two-thirds of the shin.", "vi": "Quần võ phục Karate Gi phải che phủ ít nhất hai phần ba ống chân."},
    4: {"en": "The Karate Gi jacket sleeves must be no longer than the bend of the wrist.", "vi": "Tay áo của áo võ phục Karate Gi phải không dài hơn nếp gấp của cổ tay."},
    5: {"en": "If an Athlete's Karate Gi jacket sleeves are too long and a suitable replacement cannot be found in time the Referee can allow him to turn them up on the inside.", "vi": "Nếu tay áo võ phục Karate Gi của một vận động viên quá dài và không thể tìm được áo thay thế phù hợp kịp thời, trọng tài chính có thể cho phép vận động viên xắn tay áo lên ở mặt trong."},
    6: {"en": "Athletes can wear 1 or 2 discreet rubber bands on a single ponytail. Ribbons, beads and other decorations are prohibited.", "vi": "Vận động viên có thể dùng 1 hoặc 2 dây thun kín đáo trên một đuôi tóc duy nhất. Ruy băng, hạt trang trí và các vật trang trí khác bị cấm."},
    7: {"en": "Earrings are allowed if they are covered with tape.", "vi": "Khuyên tai được phép nếu chúng được dán băng keo che lại."},
    8: {"en": "Metallic teeth braces can be worn at the Athlete's own risk if approved by the Referee and the Official Doctor.", "vi": "Niềng răng bằng kim loại có thể được đeo với rủi ro do vận động viên tự chịu nếu được trọng tài chính và Bác sĩ chính thức phê duyệt."},
    9: {"en": "Athletes must bow properly to each other at the start and end of the bout.", "vi": "Các vận động viên phải chào nhau đúng cách ở đầu và cuối trận đấu."},
    10: {"en": "The Coach can change the team fighting order during a match.", "vi": "Huấn luyện viên có thể thay đổi thứ tự thi đấu của đội trong một trận đấu."},
    11: {"en": "If an Athlete is injured in an individual bout the Coach can enter a replacement if he notifies the Organising Commission first.", "vi": "Nếu một vận động viên bị chấn thương trong một trận đấu cá nhân, huấn luyện viên có thể đăng ký người thay thế nếu huấn luyện viên thông báo trước cho Ban Tổ chức."},
    12: {"en": "Each Judge must be equipped with a red and a blue flag or joysticks.", "vi": "Mỗi giám định phải được trang bị một cờ đỏ và một cờ xanh hoặc cần điều khiển (joystick)."},
    13: {"en": "If two teams have the same number of victories and points, a deciding bout will be held.", "vi": "Nếu hai đội có cùng số trận thắng và cùng số điểm, một trận đấu phân định thắng thua sẽ được tổ chức."},
    14: {"en": "The Match Supervisor (KANSA) will be equipped with only a whistle.", "vi": "Giám sát trận đấu (KANSA) sẽ chỉ được trang bị một chiếc còi."},
    15: {"en": "Disqualification by KIKEN means that the Athletes are disqualified from that category.", "vi": "Truất quyền thi đấu bằng KIKEN có nghĩa là các vận động viên bị truất quyền thi đấu khỏi hạng mục đó."},
    16: {"en": "Heels of more than 4 cm must not be worn with the uniform.", "vi": "Gót giày cao hơn 4 cm không được mang cùng với đồng phục."},
    17: {"en": "Senior Male bouts are three minutes, and Senior Female, Cadets, and Juniors, two minutes.", "vi": "Các trận đấu Nam lứa tuổi Senior kéo dài ba phút, và các trận đấu Nữ lứa tuổi Senior, Cadet và Junior kéo dài hai phút."},
    18: {"en": "Kumite team members can wear any type of Karate Gi.", "vi": "Các thành viên đội Kumite có thể mặc bất kỳ loại võ phục Karate Gi nào."},
    19: {"en": "Different Karate Gi brands can be used for team members.", "vi": "Các nhãn hiệu võ phục Karate Gi khác nhau có thể được sử dụng cho các thành viên của đội."},
    20: {"en": "An Athlete does not need to change the jacket if the ties are torn off during the bout.", "vi": "Một vận động viên không cần thay áo nếu các dây buộc bị đứt ra trong trận đấu."},
    21: {"en": "Athletes can wear any white Karate Gi.", "vi": "Vận động viên có thể mặc bất kỳ võ phục Karate Gi màu trắng nào."},
    22: {"en": "A fast combination of CHUDAN KERI and TSUKI each of which score in their own right will be given IPPON.", "vi": "Một tổ hợp đòn nhanh gồm CHUDAN KERI và TSUKI, mỗi đòn đều tự nó đủ điều kiện ghi điểm, sẽ được cho IPPON."},
    23: {"en": "In Senior bouts a light \"skin touch\" to the throat does not need to result in a warning or penalty provided there is no injury.", "vi": "Trong các trận đấu lứa tuổi Senior, một cú “chạm da” (skin touch) nhẹ vào cổ họng không nhất thiết phải dẫn đến cảnh cáo hoặc xử phạt, miễn là không có chấn thương."},
    24: {"en": "A kick in the groin will not result in a penalty provided the offender did not do it intentionally.", "vi": "Một cú đá vào hạ bộ sẽ không dẫn đến xử phạt, miễn là người phạm lỗi không cố ý thực hiện."},
    25: {"en": "For Athletes under 14 years of age, the WKF approved protective helmet is compulsory.", "vi": "Đối với vận động viên dưới 14 tuổi, mũ bảo hộ được WKF phê duyệt là bắt buộc."},
    26: {"en": "If SENSHU is withdrawn when it is less than 15 seconds left of the bout, no further SENSHU can be awarded to either Athlete.", "vi": "Nếu SENSHU bị rút lại khi trận đấu còn ít hơn 15 giây, không vận động viên nào trong hai vận động viên có thể được trao SENSHU nữa."},
    27: {"en": "If an Athlete, that has been awarded SENSHU, receives a warning for avoiding combat when there is less than 15 seconds left of the bout – the Athlete will automatically forfeit this advantage.", "vi": "Nếu một vận động viên đã được trao SENSHU nhận một cảnh cáo vì né tránh thi đấu khi trận đấu còn ít hơn 15 giây, vận động viên đó sẽ tự động mất lợi thế này."},
    28: {"en": "Voluntary religious headwear must be approved by WKF.", "vi": "Khăn trùm đầu tôn giáo tự nguyện phải được WKF phê duyệt."},
    29: {"en": "The WKF Competition Supervisor, or the Organizing Commission, can allow Coaches to use any t-shirt instead of the track suit jacket.", "vi": "Giám sát thi đấu của WKF, hoặc Ban Tổ chức, có thể cho phép các huấn luyện viên sử dụng bất kỳ áo thun nào thay cho áo khoác của bộ đồ thể thao."},
    30: {"en": "HANSOKU CHUI is given if the Athlete's potential for winning has been reduced by the opponent's foul.", "vi": "HANSOKU CHUI được áp dụng nếu khả năng giành chiến thắng của vận động viên đã bị giảm sút do lỗi của đối thủ."},
    31: {"en": "The weight tolerance admitted for male and female is 0.5 kg.", "vi": "Dung sai cân nặng cho phép đối với nam và nữ là 0,5 kg."},
    32: {"en": "HANSOKU is imposed for very serious rules infractions.", "vi": "HANSOKU được áp dụng đối với các vi phạm luật rất nghiêm trọng."},
    33: {"en": "SHIKKAKU can only be imposed after a warning has been given.", "vi": "SHIKKAKU chỉ có thể được áp dụng sau khi đã đưa ra một cảnh cáo."},
    34: {"en": "If an Athlete acts maliciously, SHIKKAKU and not HANSOKU is the correct penalty.", "vi": "Nếu một vận động viên hành xử ác ý, SHIKKAKU chứ không phải HANSOKU là hình phạt đúng."},
    35: {"en": "If an Athlete acts maliciously, HANSOKU is the correct penalty.", "vi": "Nếu một vận động viên hành xử ác ý, HANSOKU là hình phạt đúng."},
    36: {"en": "An Athlete can be given SHIKKAKU if the behaviour of the Coach or non- combatant members of the Athlete's delegation is considered to harm the prestige and honour of Karate-Do.", "vi": "Một vận động viên có thể bị áp dụng SHIKKAKU nếu hành vi của huấn luyện viên hoặc các thành viên không thi đấu trong đoàn của vận động viên bị coi là làm tổn hại đến uy tín và danh dự của Karate-Do."},
    37: {"en": "For individual competition, the Round-robin system followed by quarterfinals, semifinals and final is applied.", "vi": "Đối với thi đấu cá nhân, hệ thống vòng tròn tiếp nối bằng tứ kết, bán kết và chung kết được áp dụng."},
    38: {"en": "There are five criteria to be met in determining a score.", "vi": "Có năm tiêu chí phải đáp ứng để xác định một điểm số."},
    39: {"en": "A male team must present a minimum of five Athletes for the initial round.", "vi": "Một đội nam phải trình diện tối thiểu năm vận động viên cho vòng đầu tiên."},
    40: {"en": "Male Kumite teams in the elimination format comprise five to seven members with five competing in the first round.", "vi": "Các đội Kumite nam trong thể thức loại trực tiếp gồm từ năm đến bảy thành viên, với năm người thi đấu ở vòng đầu tiên."},
    41: {"en": "A female team must present a minimum of two Athletes for the initial round.", "vi": "Một đội nữ phải trình diện tối thiểu hai vận động viên cho vòng đầu tiên."},
    42: {"en": "If the Coach continues to interfere after the first warning, the Referee will stop the bout, approach again and ask the Coach to leave the Tatami.", "vi": "Nếu huấn luyện viên tiếp tục can thiệp sau cảnh cáo đầu tiên, trọng tài chính sẽ dừng trận đấu, lại tiến đến gần và yêu cầu huấn luyện viên rời khỏi thảm đấu (Tatami)."},
    43: {"en": "If AKA scores just as AO steps outside of the competition area, both the score and warning or penalty can be given.", "vi": "Nếu AKA ghi điểm đúng lúc AO bước ra ngoài khu vực thi đấu, cả điểm số và cảnh cáo hoặc xử phạt đều có thể được đưa ra."},
    44: {"en": "If an Athlete has been physically propelled from the area, JOGAI will be given.", "vi": "Nếu một vận động viên đã bị đẩy văng ra khỏi khu vực thi đấu, JOGAI sẽ được áp dụng."},
    45: {"en": "In Premier League competition, the losers to the finalists in the quarterfinals and semifinals compete for the bronze medals.", "vi": "Trong thi đấu Premier League, những người thua trước các vận động viên vào chung kết ở tứ kết và bán kết sẽ thi đấu tranh huy chương đồng."},
    46: {"en": "In Round-robin, in cases where there is a tie between two or more Athletes in a group, having the same number of total points, the first criterion to consider is the highest World Ranking at the date of the competition.", "vi": "Trong thi đấu vòng tròn, trong các trường hợp có hai hoặc nhiều vận động viên trong một nhóm hòa nhau, có cùng tổng số điểm, tiêu chí đầu tiên cần xem xét là thứ hạng Thế giới cao nhất tại ngày thi đấu."},
    47: {"en": "It is possible for an Athlete to be disqualified from a bout (HANSOKU) and continue the competition.", "vi": "Một vận động viên có thể bị truất quyền thi đấu khỏi một trận đấu (HANSOKU) và vẫn tiếp tục thi đấu trong giải."},
    48: {"en": "An Athlete who scores and exits the area before the Referee calls YAME will not receive JOGAI.", "vi": "Một vận động viên ghi điểm và rời khỏi khu vực trước khi trọng tài chính hô YAME sẽ không bị áp dụng JOGAI."},
    49: {"en": "Athletes cannot be given penalties after the time-up bell has signalled the end of a bout.", "vi": "Vận động viên không thể bị xử phạt sau khi chuông hết giờ đã báo hiệu kết thúc một trận đấu."},
    50: {"en": "Any technique to the face, head or neck, which causes injury will be warned or penalised unless it is the recipient's own fault.", "vi": "Bất kỳ kỹ thuật nào vào mặt, đầu hoặc cổ gây chấn thương sẽ bị cảnh cáo hoặc xử phạt, trừ khi đó là lỗi của chính người nhận đòn."},
    51: {"en": "In Cadet and Junior competition JODAN techniques are allowed to make \"skin touch\" provided there is no injury.", "vi": "Trong thi đấu Cadet và Junior, các kỹ thuật JODAN được phép “chạm da” (skin touch), miễn là không có chấn thương."},
    52: {"en": "In Senior competition a light touch is allowed for JODAN punches, and a greater tolerance is allowed for JODAN kicks.", "vi": "Trong thi đấu Senior, chạm nhẹ được phép đối với các đòn đấm JODAN, và mức dung sai lớn hơn được phép đối với các đòn đá JODAN."},
    53: {"en": "An already qualified Athlete cannot be disqualified for misconduct (SHIKKAKU) at the end of the Round-robin.", "vi": "Một vận động viên đã giành quyền đi tiếp không thể bị truất quyền thi đấu vì hành vi sai trái (SHIKKAKU) khi giai đoạn vòng tròn kết thúc."},
    54: {"en": "If a variation of the competition format other than described in the rules is to be applied for a particular tournament, this has to be clearly announced in the tournament bulletin.", "vi": "Nếu một biến thể của thể thức thi đấu khác với thể thức được mô tả trong luật sẽ được áp dụng cho một giải đấu cụ thể, điều này phải được thông báo rõ ràng trong bản tin của giải đấu."},
    55: {"en": "If an Athlete has been asked before the bout starts, and confirms wearing a groin guard, and it later proves that this is not so, the Athlete will receive SHIKKAKU.", "vi": "Nếu một vận động viên đã được hỏi trước khi trận đấu bắt đầu và xác nhận có đeo bảo hộ hạ bộ, và sau đó chứng tỏ điều này là không đúng, vận động viên sẽ nhận SHIKKAKU."},
    56: {"en": "When the Judges see a score, they will immediately signal it with their joystick or flag.", "vi": "Khi các giám định thấy một điểm số, họ sẽ ngay lập tức ra hiệu bằng cần điều khiển hoặc cờ của mình."},
    57: {"en": "The Referee Panel is composed of one Tatami Manager and three Tatami Manager Assistants.", "vi": "Tổ trọng tài gồm một Quản lý thảm đấu và ba Trợ lý quản lý thảm đấu."},
    58: {"en": "The Referee Panel for each bout shall consist of one Referee, four Judges and one Match Supervisor.", "vi": "Tổ trọng tài cho mỗi trận đấu gồm một trọng tài chính, bốn giám định và một giám sát trận đấu."},
    59: {"en": "If after the bout has started, an Athlete is found not to be wearing a gum shield, the Athlete will be disqualified.", "vi": "Nếu sau khi trận đấu đã bắt đầu, phát hiện một vận động viên không đeo bảo hộ răng (gum shield), vận động viên sẽ bị truất quyền thi đấu."},
    60: {"en": "The Referee will give all commands and make all announcements.", "vi": "Trọng tài chính sẽ đưa ra mọi hiệu lệnh và thực hiện mọi thông báo."},
    61: {"en": "Duration of the Kumite bout is 1.5 minutes for under 14 years.", "vi": "Thời lượng của trận đấu Kumite là 1,5 phút đối với lứa tuổi dưới 14 tuổi."},
    62: {"en": "If three Judges signal a score for AKA, the Referee must stop the bout even if he believes they are mistaken.", "vi": "Nếu ba giám định ra hiệu điểm cho AKA, trọng tài chính phải dừng trận đấu ngay cả khi trọng tài chính tin rằng họ đã nhầm."},
    63: {"en": "If two or more Judges signal a score for the same Athlete, the Referee must stop the bout.", "vi": "Nếu từ hai giám định trở lên ra hiệu điểm cho cùng một vận động viên, trọng tài chính phải dừng trận đấu."},
    64: {"en": "The timing of a bout starts when the Referee gives the signal to start and stops when the Referee calls \"YAME\" or when the time is up.", "vi": "Việc tính giờ của một trận đấu bắt đầu khi trọng tài chính ra hiệu bắt đầu và dừng khi trọng tài chính hô “YAME” hoặc khi hết giờ."},
    65: {"en": "The Referee Panel shall consist of one Referee, four Judges, one Match Supervisor and one Score Keeper.", "vi": "Tổ trọng tài gồm một trọng tài chính, bốn giám định, một giám sát trận đấu và một người ghi điểm."},
    66: {"en": "The Athlete's Coach is the only one allowed to make a protest.", "vi": "Huấn luyện viên của vận động viên là người duy nhất được phép nộp khiếu nại."},
    67: {"en": "If the Referee does not hear the time-up signal, KANSA will blow the whistle.", "vi": "Nếu trọng tài chính không nghe thấy tín hiệu hết giờ, KANSA sẽ thổi còi."},
    68: {"en": "The Athletes must only bow properly to each other at the start of the bout.", "vi": "Các vận động viên chỉ phải chào nhau đúng cách ở đầu trận đấu."},
    69: {"en": "In individual bouts an Athlete who withdraws voluntarily from the bout is declared KIKEN and an extra eight points are awarded to the opponent.", "vi": "Trong các trận đấu cá nhân, một vận động viên tự nguyện rút khỏi trận đấu sẽ bị tuyên bố KIKEN và đối thủ được cộng thêm tám điểm."},
    70: {"en": "Awareness is the state of continued commitment, which endures after the technique has landed.", "vi": "Nhận thức duy trì (Awareness) là trạng thái tiếp tục dấn thân, kéo dài sau khi kỹ thuật đã chạm đích."},
    71: {"en": "If the organizer has a check-up of equipment before line-up, it is still KANSA's responsibility to ensure that the equipment is in accordance with the rules.", "vi": "Nếu ban tổ chức có kiểm tra thiết bị trước khi xếp hàng, KANSA vẫn có trách nhiệm bảo đảm thiết bị phù hợp với luật."},
    72: {"en": "An Athlete who stays within the competition area can score on an Athlete outside the competition area.", "vi": "Một vận động viên đứng trong khu vực thi đấu có thể ghi điểm lên một vận động viên ở ngoài khu vực thi đấu."},
    73: {"en": "ATO SHIBARAKU means \"15 seconds of bout time remaining\".", "vi": "ATO SHIBARAKU có nghĩa là “trận đấu còn 15 giây”."},
    74: {"en": "ATO SHIBARAKU means \"10 seconds of bout time remaining\".", "vi": "ATO SHIBARAKU có nghĩa là “trận đấu còn 10 giây”."},
    75: {"en": "A \"skin touch\" to the throat is allowed only in Senior competition.", "vi": "“Chạm da” vào cổ họng chỉ được phép trong thi đấu Senior."},
    76: {"en": "If there are no points at the end of a bout in team matches the Referee will call for HANTEI.", "vi": "Nếu không có điểm nào ở cuối một trận đấu trong các trận đồng đội, trọng tài chính sẽ yêu cầu HANTEI."},
    77: {"en": "If an Athlete has been asked before the bout starts, and confirms wearing a groin guard, and it later proves that this is not so, the Athlete will receive a warning or penalty for MUBOBI.", "vi": "Nếu một vận động viên đã được hỏi trước khi trận đấu bắt đầu và xác nhận có đeo bảo hộ hạ bộ, và sau đó chứng tỏ điều này là không đúng, vận động viên sẽ nhận một cảnh cáo hoặc xử phạt vì MUBOBI."},
    78: {"en": "An Athlete can be penalised for exaggeration even if there is an actual injury.", "vi": "Một vận động viên có thể bị xử phạt vì phóng đại ngay cả khi có chấn thương thực tế."},
    79: {"en": "The Referee declares the winner, \"AO (AKA) NO KACHI\", and if necessary, breaks the tie in case of HANTEI.", "vi": "Trọng tài chính tuyên bố người chiến thắng, “AO (AKA) NO KACHI”, và nếu cần thiết, phân định trường hợp hòa trong trường hợp HANTEI."},
    80: {"en": "In the event of a tied score at the end of an inconclusive bout the Referee and the four Judges will decide the bout by HANTEI.", "vi": "Trong trường hợp điểm số hòa vào cuối một trận đấu không phân định được, trọng tài chính và bốn giám định sẽ quyết định trận đấu bằng HANTEI."},
    81: {"en": "If the Referee Panel has made a decision not in accordance with the Rules of Competition, KANSA will immediately blow his whistle.", "vi": "Nếu Tổ trọng tài đã đưa ra một quyết định không phù hợp với Quy định Thi đấu, KANSA sẽ ngay lập tức thổi còi."},
    82: {"en": "An Athlete should not be penalized for being winded (loss of breath as a consequence of a technique) or simply reacting to an impact even if the technique merited a point by the opponent.", "vi": "Một vận động viên không nên bị xử phạt vì bị hụt hơi (mất hơi thở do hậu quả của một kỹ thuật) hoặc đơn giản là phản ứng với một va chạm ngay cả khi kỹ thuật đó xứng đáng được điểm cho đối thủ."},
    83: {"en": "In team matches, there is no extra bout.", "vi": "Trong các trận đồng đội, không có trận đấu phụ thêm."},
    84: {"en": "Only the first correctly executed technique of a combination will score.", "vi": "Chỉ kỹ thuật đầu tiên được thực hiện đúng trong một tổ hợp đòn mới ghi điểm."},
    85: {"en": "Athletes that appear at the competition area with unauthorized equipment or irregular Karate Gi, will be given one minute to correct the attire.", "vi": "Các vận động viên xuất hiện tại khu vực thi đấu với thiết bị không được phép hoặc võ phục Karate Gi không đúng quy định sẽ được cho một phút để sửa lại trang phục."},
    86: {"en": "Athletes that are winded as a result of an impact, should be allowed time to catch their breath before the bout is resumed.", "vi": "Các vận động viên bị hụt hơi do một va chạm phải được cho thời gian để lấy lại hơi thở trước khi trận đấu được tiếp tục."},
    87: {"en": "JODAN is described as the shoulders and the area above the collarbones.", "vi": "JODAN được mô tả là vai và vùng ở phía trên xương đòn."},
    88: {"en": "IPPON is awarded for JODAN kicks or any techniques against an opponent whose any part of the body other than the feet is in contact with the Tatami.", "vi": "IPPON được trao cho các đòn đá JODAN hoặc bất kỳ kỹ thuật nào lên một đối thủ mà bất kỳ bộ phận nào của cơ thể ngoài bàn chân đang tiếp xúc với thảm đấu (Tatami)."},
    89: {"en": "HANSOKU CHUI will be given for feigning of injury.", "vi": "HANSOKU CHUI sẽ được áp dụng đối với việc giả vờ chấn thương."},
    90: {"en": "HANSOKU will be given for the first instance of exaggerating an injury.", "vi": "HANSOKU sẽ được áp dụng đối với trường hợp phóng đại chấn thương đầu tiên."},
    91: {"en": "A loss of breath by the recipient of a CHUDAN technique indicates lack of control.", "vi": "Việc người nhận một kỹ thuật CHUDAN bị mất hơi thở cho thấy sự thiếu kiểm soát."},
    92: {"en": "An Athlete can be given HANSOKU directly for exaggerating the effects of injury.", "vi": "Một vận động viên có thể bị áp dụng HANSOKU trực tiếp vì phóng đại tác động của chấn thương."},
    93: {"en": "A technique, even if effective, delivered after an order to suspend or halt the bout will not score and can result in a penalty being imposed on the offender.", "vi": "Một kỹ thuật, ngay cả khi hiệu quả, được thực hiện sau một lệnh tạm dừng hoặc dừng trận đấu sẽ không ghi điểm và có thể dẫn đến việc người phạm lỗi bị xử phạt."},
    94: {"en": "If there is an error in the draw and the wrong Athletes compete, this cannot be changed afterwards.", "vi": "Nếu có sai sót trong việc bốc thăm và các vận động viên không đúng thi đấu với nhau, điều này không thể thay đổi sau đó."},
    95: {"en": "Correctly executed techniques landed at the moment the time runs out are valid.", "vi": "Các kỹ thuật được thực hiện đúng và chạm đích vào thời điểm hết giờ là hợp lệ."},
    96: {"en": "If an Athlete is injured and it is considered to be their own fault (MUBOBI), the Referee will decline to give a warning or penalty to the opponent.", "vi": "Nếu một vận động viên bị chấn thương và được coi là do lỗi của chính họ (MUBOBI), trọng tài chính sẽ từ chối đưa ra cảnh cáo hoặc xử phạt cho đối thủ."},
    97: {"en": "KANSA has no vote or authority in matters of judgments, such as whether a score was valid or not, unless there has been an error in the application of the rules.", "vi": "KANSA không có quyền bỏ phiếu hoặc thẩm quyền trong các vấn đề phán xét, chẳng hạn như một điểm số có hợp lệ hay không, trừ khi đã có sai sót trong việc áp dụng luật."},
    98: {"en": "YUKO is always awarded for punches on the back.", "vi": "YUKO luôn được trao cho các đòn đấm vào lưng."},
    99: {"en": "\"Skin touch\" is allowed in all official categories.", "vi": "“Chạm da” (skin touch) được phép trong mọi hạng mục chính thức."},
    100: {"en": "An Athlete who does not obey the Referee's orders will be given SHIKKAKU.", "vi": "Một vận động viên không tuân theo mệnh lệnh của trọng tài chính sẽ bị áp dụng SHIKKAKU."},
    101: {"en": "The Score Supervisor will order the Referee to halt the bout if there is a contravention of the rules.", "vi": "Giám sát bảng điểm sẽ yêu cầu trọng tài chính dừng trận đấu nếu có vi phạm luật."},
    102: {"en": "If in a combination, the first technique merits a YUKO and the second merits a penalty, both shall be given.", "vi": "Nếu trong một tổ hợp đòn, kỹ thuật đầu tiên xứng đáng được YUKO và kỹ thuật thứ hai xứng đáng bị xử phạt, cả hai đều sẽ được áp dụng."},
    103: {"en": "\"Skin touch\" is defined as touching the target without transferring energy into the protective helmet or head of the Athlete.", "vi": "“Chạm da” được định nghĩa là chạm vào mục tiêu mà không truyền năng lượng vào mũ bảo hộ hoặc đầu của vận động viên."},
    104: {"en": "It is not possible to score while lying on the floor.", "vi": "Không thể ghi điểm khi đang nằm trên sàn."},
    105: {"en": "An Athlete not wearing the WKF approved equipment will be given two minutes to change for the approved type.", "vi": "Một vận động viên không mặc thiết bị đã được WKF phê duyệt sẽ được cho hai phút để thay sang loại đã được phê duyệt."},
    106: {"en": "An Athlete injured in Kumite and withdrawn under the ten-second rule cannot compete in the Kata competition.", "vi": "Một vận động viên bị chấn thương trong Kumite và bị rút khỏi thi đấu theo quy tắc mười giây không thể thi đấu trong nội dung Kata."},
    107: {"en": "An injured Athlete who has been declared unfit to fight by the Tournament Doctor cannot fight again in that competition.", "vi": "Một vận động viên bị chấn thương đã được Bác sĩ của giải đấu tuyên bố không đủ điều kiện thi đấu không thể thi đấu lại trong giải đấu đó."},
    108: {"en": "If an Athlete behaves badly on the competition area after the end of the bout or match, the Referee can still give SHIKKAKU.", "vi": "Nếu một vận động viên cư xử xấu trên khu vực thi đấu sau khi trận đấu hoặc trận đồng đội kết thúc, trọng tài chính vẫn có thể áp dụng SHIKKAKU."},
    109: {"en": "KANSA has a vote in cases of SHIKKAKU.", "vi": "KANSA có quyền bỏ phiếu trong các trường hợp SHIKKAKU."},
    110: {"en": "In Male team matches if a team wins three bouts, then the match is over at that point.", "vi": "Trong các trận đồng đội nam, nếu một đội thắng ba trận đấu, trận đồng đội sẽ kết thúc tại thời điểm đó."},
    111: {"en": "In Female team matches if a team wins two bouts, then the match is over at that point.", "vi": "Trong các trận đồng đội nữ, nếu một đội thắng hai trận đấu, trận đồng đội sẽ kết thúc tại thời điểm đó."},
    112: {"en": "If an Athlete seizes the opponent and does not perform an immediate technique or throw the Referee will call \"YAME\".", "vi": "Nếu một vận động viên túm giữ đối thủ và không thực hiện ngay một kỹ thuật hoặc một đòn ném, trọng tài chính sẽ hô “YAME”."},
    113: {"en": "An Athlete who commits an act which harms the prestige and honour of Karate- Do will be given HANSOKU.", "vi": "Một vận động viên thực hiện một hành vi làm tổn hại đến uy tín và danh dự của Karate-Do sẽ bị áp dụng HANSOKU."},
    114: {"en": "If an action of an Athlete is considered to be dangerous and deliberately violates the rules concerning prohibited behaviour, the Athlete will be given SHIKKAKU.", "vi": "Nếu một hành động của vận động viên bị coi là nguy hiểm và cố ý vi phạm các quy định về hành vi bị cấm, vận động viên sẽ bị áp dụng SHIKKAKU."},
    115: {"en": "Correctly executed techniques after the time-up signal are valid.", "vi": "Các kỹ thuật được thực hiện đúng sau tín hiệu hết giờ là hợp lệ."},
    116: {"en": "Correctly executed techniques upon or after \"WAKARETE\" are valid.", "vi": "Các kỹ thuật được thực hiện đúng vào lúc hoặc sau “WAKARETE” là hợp lệ."},
    117: {"en": "At HANTEI, if three Judges signal victory for AKA and the fourth Judge signals victory for AO, the Referee must give victory for AKA.", "vi": "Tại HANTEI, nếu ba giám định ra hiệu chiến thắng cho AKA và giám định thứ tư ra hiệu chiến thắng cho AO, trọng tài chính phải tuyên bố chiến thắng cho AKA."},
    118: {"en": "Passivity cannot be given to an Athlete having a lead by points or SENSHU.", "vi": "Tính thụ động không thể bị áp dụng cho một vận động viên đang dẫn trước về điểm hoặc SENSHU."},
    119: {"en": "Only the Coach designated for the specific bout is allowed to guide the Athlete from the place allocated to the Coach close to the competition area.", "vi": "Chỉ huấn luyện viên được chỉ định cho trận đấu cụ thể đó mới được phép hướng dẫn vận động viên từ vị trí dành cho huấn luyện viên gần khu vực thi đấu."},
    120: {"en": "If an Athlete does not regain his or her feet within ten seconds, the Referee will announce \"KIKEN\" and \"KACHI\" to the opponent.", "vi": "Nếu một vận động viên không đứng dậy được trong vòng mười giây, trọng tài chính sẽ tuyên bố “KIKEN” và “KACHI” cho đối thủ."},
    121: {"en": "If an Athlete is thrown and lands partly outside the competition area, the Referee will immediately call \"YAME\".", "vi": "Nếu một vận động viên bị ném và tiếp đất một phần ở ngoài khu vực thi đấu, trọng tài chính sẽ ngay lập tức hô “YAME”."},
    122: {"en": "The Athlete is not allowed to signal to the Coach to request a video review.", "vi": "Vận động viên không được phép ra hiệu cho huấn luyện viên để yêu cầu xem lại video."},
    123: {"en": "The Athlete should be examined outside the Tatami.", "vi": "Vận động viên phải được khám ở ngoài thảm đấu (Tatami)."},
    124: {"en": "KANSA has to blow the whistle if the Judges are holding the joysticks in the wrong hands.", "vi": "KANSA phải thổi còi nếu các giám định đang cầm cần điều khiển ở sai tay."},
    125: {"en": "Gum-shields are obligatory for all Kumite Athletes.", "vi": "Bảo hộ răng (gum shield) là bắt buộc đối với mọi vận động viên Kumite."},
    126: {"en": "After a throw the Referee will allow a maximum of two seconds for a score to be made.", "vi": "Sau một đòn ném, trọng tài chính sẽ cho tối đa hai giây để ghi điểm."},
    127: {"en": "If an Athlete scores with a strong kick and propels the opponent out of the area, the Referee should award WAZA-ARI and give the opponent a warning or penalty for JOGAI.", "vi": "Nếu một vận động viên ghi điểm bằng một đòn đá mạnh và đẩy đối thủ ra khỏi khu vực, trọng tài chính phải trao WAZA-ARI và đưa ra cảnh cáo hoặc xử phạt cho đối thủ vì JOGAI."},
    128: {"en": "If an official protest is lodged the ensuing bouts must be delayed until the result of the protest is given.", "vi": "Nếu một khiếu nại chính thức được nộp, các trận đấu tiếp theo phải bị hoãn cho đến khi kết quả của khiếu nại được công bố."},
    129: {"en": "If the Referee awards a point for a technique which has caused injury KANSA should signal for the bout to be stopped.", "vi": "Nếu trọng tài chính trao điểm cho một kỹ thuật đã gây chấn thương, KANSA phải ra hiệu cho trận đấu dừng lại."},
    130: {"en": "If the Referee fails to hear the time-up bell, the Scorekeeper should whistle.", "vi": "Nếu trọng tài chính không nghe thấy chuông hết giờ, người ghi điểm phải thổi còi."},
    131: {"en": "WAKARETE for breaking up a clinch can be given at any time of the bout.", "vi": "WAKARETE để tách một tình trạng ôm giữ (clinch) có thể được đưa ra vào bất kỳ thời điểm nào của trận đấu."},
    132: {"en": "FUKUSHIN SHUGO is obligatory before imposing SHIKKAKU.", "vi": "FUKUSHIN SHUGO là bắt buộc trước khi áp dụng SHIKKAKU."},
    133: {"en": "If an Athlete is injured during a bout and needs medical treatment three minutes will be given in which to receive it, after that the Referee will decide whether the Athlete should be declared unfit to fight or whether more time should be given.", "vi": "Nếu một vận động viên bị chấn thương trong một trận đấu và cần điều trị y tế, ba phút sẽ được dành để vận động viên nhận điều trị, sau đó trọng tài chính sẽ quyết định vận động viên có nên bị tuyên bố không đủ điều kiện thi đấu hay nên được cho thêm thời gian."},
    134: {"en": "An Athlete who exits the competition area (JOGAI) with less than 15 seconds of bout time remaining will be given a minimum of CHUI.", "vi": "Một vận động viên rời khỏi khu vực thi đấu (JOGAI) khi trận đấu còn ít hơn 15 giây sẽ bị áp dụng tối thiểu CHUI."},
    135: {"en": "To correct a score given to the wrong Athlete, the Referee should turn towards the Athlete given the score in error, make the sign of TORIMASEN, and then give the score to the opponent.", "vi": "Để sửa một điểm số đã trao cho vận động viên không đúng, trọng tài chính phải quay về phía vận động viên đã được trao điểm do nhầm lẫn, làm dấu hiệu TORIMASEN, và sau đó trao điểm cho đối thủ."},
    136: {"en": "If an Athlete scores with a well-controlled CHUDAN kick, then accidentally punches his opponent in the face causing a slight injury, WAZA-ARI and a warning should be given.", "vi": "Nếu một vận động viên ghi điểm bằng một đòn đá CHUDAN được kiểm soát tốt, sau đó vô tình đấm vào mặt đối thủ gây chấn thương nhẹ, WAZA-ARI và một cảnh cáo phải được áp dụng."},
    137: {"en": "If an injured Athlete has been given medical treatment and the Official Doctor says that the Athlete can continue fighting the Referee cannot overrule the Doctor's decision.", "vi": "Nếu một vận động viên bị chấn thương đã được điều trị y tế và Bác sĩ chính thức nói rằng vận động viên có thể tiếp tục thi đấu, trọng tài chính không thể bác bỏ quyết định của Bác sĩ."},
    138: {"en": "The Referee can stop the bout even if the Judges do not signal.", "vi": "Trọng tài chính có thể dừng trận đấu ngay cả khi các giám định không ra hiệu."},
    139: {"en": "Once WAKARETE is called by the Referee the Coaches do not have the opportunity to make a video review request unless the techniques happened before WAKARETE was called.", "vi": "Một khi trọng tài chính đã hô WAKARETE, các huấn luyện viên không có cơ hội đưa ra yêu cầu xem lại video trừ khi các kỹ thuật đã xảy ra trước khi WAKARETE được hô."},
    140: {"en": "\"Avoiding Combat\" refers to a situation where an Athlete attempts to prevent the opponent from having the opportunity to score by using time-wasting behaviour.", "vi": "“Né tránh thi đấu” chỉ một tình huống trong đó một vận động viên cố gắng ngăn cản đối thủ có cơ hội ghi điểm bằng cách sử dụng hành vi câu giờ."},
    141: {"en": "TSUZUKETE, unless preceded by WAKARETE, is not used if there is less than 15 seconds left of the bout.", "vi": "TSUZUKETE, trừ khi được hô trước bởi WAKARETE, không được sử dụng nếu trận đấu còn ít hơn 15 giây."},
    142: {"en": "In team matches if two Athletes injure each other and are unable to continue, and the score is equal, the Referee will announce HIKIWAKE.", "vi": "Trong các trận đồng đội, nếu hai vận động viên làm nhau bị chấn thương và không thể tiếp tục, và điểm số bằng nhau, trọng tài chính sẽ tuyên bố HIKIWAKE."},
    143: {"en": "if there are less than 15 seconds of bout time remaining and a losing Athlete, desperately trying to equalise, exits the area (JOGAI) the Athlete will be given a minimum of HANSOKU CHUI.", "vi": "Nếu trận đấu còn ít hơn 15 giây và một vận động viên đang thua, trong nỗ lực tuyệt vọng nhằm cân bằng tỷ số, rời khỏi khu vực (JOGAI), vận động viên sẽ bị áp dụng tối thiểu HANSOKU CHUI."},
    144: {"en": "Techniques which land below the belt cannot score.", "vi": "Các kỹ thuật chạm đích ở dưới đai không thể ghi điểm."},
    145: {"en": "Techniques, which land on the shoulder blade, can score.", "vi": "Các kỹ thuật chạm đích vào xương bả vai có thể ghi điểm."},
    146: {"en": "If AKA accidentally kicks AO on the hip and AO cannot continue the bout, then AO will be given KIKEN.", "vi": "Nếu AKA vô tình đá vào hông của AO và AO không thể tiếp tục trận đấu, AO sẽ bị áp dụng KIKEN."},
    147: {"en": "If an Athlete is obviously out of breath due to lack of endurance, the Referee should stop the bout to give the Athlete time to recover.", "vi": "Nếu một vận động viên rõ ràng bị hụt hơi do thiếu sức bền, trọng tài chính phải dừng trận đấu để cho vận động viên thời gian hồi phục."},
    148: {"en": "An Athlete who establishes a clear lead of eight points is declared the winner.", "vi": "Một vận động viên thiết lập khoảng cách dẫn trước rõ ràng tám điểm sẽ được tuyên bố là người chiến thắng."},
    149: {"en": "When time is up, the Athlete who has scored the most points is declared the winner.", "vi": "Khi hết giờ, vận động viên ghi được nhiều điểm nhất sẽ được tuyên bố là người chiến thắng."},
    150: {"en": "An otherwise correctly executed technique will be penalized if executed at the same time as WAKARETE has been called.", "vi": "Một kỹ thuật vốn được thực hiện đúng theo các mặt khác sẽ bị xử phạt nếu được thực hiện cùng lúc WAKARETE được hô."},
    151: {"en": "There are two degrees of official warnings.", "vi": "Có hai mức độ cảnh cáo chính thức."},
    152: {"en": "CHUI is given, up to three times, for smaller infractions.", "vi": "CHUI được áp dụng, tối đa ba lần, đối với các vi phạm nhỏ hơn."},
    153: {"en": "HANSOKU CHUI cannot be given if three CHUI have not already been given.", "vi": "HANSOKU CHUI không thể được áp dụng nếu ba CHUI chưa được áp dụng trước đó."},
    154: {"en": "A warning or penalty for MUBOBI is only given if an Athlete is hit or injured through their own fault or negligence.", "vi": "Một cảnh cáo hoặc xử phạt vì MUBOBI chỉ được áp dụng nếu một vận động viên bị đánh trúng hoặc bị chấn thương do lỗi hoặc sơ suất của chính họ."},
    155: {"en": "An Athlete who is hit through their own fault and exaggerates the effect should receive a warning or penalty for MUBOBI or exaggeration but not both.", "vi": "Một vận động viên bị đánh trúng do lỗi của chính mình và phóng đại tác động phải nhận một cảnh cáo hoặc xử phạt vì MUBOBI hoặc vì phóng đại, nhưng không phải cả hai."},
    156: {"en": "If an Athlete makes a good CHUDAN kick and the opponent catches the leg a score cannot be given.", "vi": "Nếu một vận động viên thực hiện một đòn đá CHUDAN tốt và đối thủ bắt được chân, điểm không thể được trao."},
    157: {"en": "An Athlete makes a JODAN kick with all six scoring criteria. The opponent puts the hand up to intercept the kick and the hand then lightly hits his own face, the Referee can give IPPON since the kick was not effectively blocked.", "vi": "Một vận động viên thực hiện một đòn đá JODAN với đủ sáu tiêu chí ghi điểm. Đối thủ đưa tay lên để chặn đòn đá và bàn tay sau đó chạm nhẹ vào mặt của chính đối thủ; trọng tài chính có thể cho IPPON vì đòn đá đã không bị chặn một cách hiệu quả."},
    158: {"en": "A male team can compete with only two Athletes.", "vi": "Một đội nam có thể thi đấu chỉ với hai vận động viên."},
    159: {"en": "Authorised advertising for WKF is displayed on the left sleeve of the Karate Gi.", "vi": "Quảng cáo được phép cho WKF được trưng bày trên tay áo bên trái của võ phục Karate Gi."},
    160: {"en": "National Federations are not allowed to put advertising on the Athlete's Karate Gi.", "vi": "Các Liên đoàn Quốc gia không được phép đặt quảng cáo trên võ phục Karate Gi của vận động viên."},
    161: {"en": "A Kumite Athlete who receives KIKEN cannot compete again in that tournament.", "vi": "Một vận động viên Kumite nhận KIKEN không thể thi đấu lại trong giải đấu đó."},
    162: {"en": "An extra bout is used only for team matches.", "vi": "Một trận đấu phụ thêm chỉ được sử dụng cho các trận đồng đội."},
    163: {"en": "KANSA needs to blow the whistle if the Referee gives a score to an Athlete and MUBOBI to the other.", "vi": "KANSA cần thổi còi nếu trọng tài chính trao điểm cho một vận động viên và MUBOBI cho vận động viên còn lại."},
    164: {"en": "Serious violation of conduct, discipline, or malicious behavior merits HANSOKU CHUI.", "vi": "Vi phạm nghiêm trọng về hành vi, kỷ luật hoặc hành xử ác ý xứng đáng nhận HANSOKU CHUI."},
    165: {"en": "In international competitions, the Referee must not have the same nationality as either of the Athletes, although one of the Judges can if both Coaches agree.", "vi": "Trong các giải đấu quốc tế, trọng tài chính không được có cùng quốc tịch với bất kỳ vận động viên nào trong hai vận động viên, mặc dù một trong các giám định có thể có cùng quốc tịch nếu cả hai huấn luyện viên đồng ý."},
    166: {"en": "KANSA will line up together with the Referee and the Judges.", "vi": "KANSA sẽ xếp hàng cùng với trọng tài chính và các giám định."},
    167: {"en": "The Coaches will be seated outside the safety area, on their respective sides facing towards the official table.", "vi": "Các huấn luyện viên sẽ ngồi ở ngoài khu vực an toàn, ở phía của mình, hướng mặt về phía bàn chính thức."},
    168: {"en": "KANSA does not need to interfere if the Referee gives a score to an Athlete and exaggeration to the other.", "vi": "KANSA không cần can thiệp nếu trọng tài chính trao điểm cho một vận động viên và lỗi phóng đại cho vận động viên còn lại."},
    169: {"en": "In team matches the Referee and the Judges will rotate for each bout-provided that all hold the required license.", "vi": "Trong các trận đồng đội, trọng tài chính và các giám định sẽ luân phiên cho mỗi trận đấu, với điều kiện tất cả đều có giấy phép yêu cầu."},
    170: {"en": "The Referee can move around the entire Tatami including the safety zones.", "vi": "Trọng tài chính có thể di chuyển trên toàn bộ thảm đấu (Tatami) kể cả các khu vực an toàn."},
    171: {"en": "The red and blue belts must be without any personal embroideries or markings.", "vi": "Các đai đỏ và xanh phải không có bất kỳ thêu cá nhân hoặc ký hiệu nào."},
    172: {"en": "Personal embroidery on the Karate Gi is allowed only in bouts for medals.", "vi": "Thêu cá nhân trên võ phục Karate Gi chỉ được phép trong các trận tranh huy chương."},
    173: {"en": "If contact is considered by the Referee to be strong, but does not diminish the Athlete's chances of winning, a warning (CHUI) can be given.", "vi": "Nếu va chạm được trọng tài chính coi là mạnh, nhưng không làm giảm cơ hội chiến thắng của vận động viên, một cảnh cáo (CHUI) có thể được áp dụng."},
    174: {"en": "An obvious overreaction to a contact will receive a CHUI.", "vi": "Một phản ứng thái quá rõ ràng đối với một va chạm sẽ nhận một CHUI."},
    175: {"en": "Judges cannot indicate a score before the Referee stops the bout.", "vi": "Các giám định không thể chỉ một điểm số trước khi trọng tài chính dừng trận đấu."},
    176: {"en": "An obvious display of exaggeration will receive HANSOKU.", "vi": "Một biểu hiện phóng đại rõ ràng sẽ nhận HANSOKU."},
    177: {"en": "Any instance of feigning an injury, however slight, will receive a minimum warning of CHUI.", "vi": "Bất kỳ trường hợp giả vờ chấn thương nào, dù nhẹ đến đâu, sẽ nhận cảnh cáo tối thiểu là CHUI."},
    178: {"en": "An obvious display of any feigning such as staggering around, falling on the floor, standing up and falling down again, and so on, will receive SHIKKAKU directly.", "vi": "Bất kỳ biểu hiện giả vờ rõ ràng nào như lảo đảo đi quanh, ngã xuống sàn, đứng dậy rồi lại ngã xuống, và những hành vi tương tự, sẽ nhận SHIKKAKU trực tiếp."},
    179: {"en": "Any feigning of an injury from a technique that in fact has been determined by the Judges as a point will as a minimum result in HANSOKU CHUI.", "vi": "Bất kỳ hành vi giả vờ chấn thương nào từ một kỹ thuật mà trên thực tế đã được các giám định xác định là một điểm số sẽ, ở mức tối thiểu, dẫn đến HANSOKU CHUI."},
    180: {"en": "If an Athlete scores with more than one consecutive technique before YAME, the Judges must show the higher score regardless of which sequence the techniques scored.", "vi": "Nếu một vận động viên ghi điểm bằng nhiều hơn một kỹ thuật liên tiếp trước YAME, các giám định phải thể hiện điểm số cao hơn bất kể các kỹ thuật ghi điểm theo trình tự nào."},
    181: {"en": "In team matches, if after the extra bout there are no scores, or it is equal scores with no SENSHU, the bout will be decided by HANTEI.", "vi": "Trong các trận đồng đội, nếu sau trận đấu phụ thêm không có điểm nào, hoặc điểm số bằng nhau và không có SENSHU, trận đấu sẽ được quyết định bằng HANTEI."},
    182: {"en": "JOGAI occurs when an Athlete exits from the competition area, and it is not caused by the opponent.", "vi": "JOGAI xảy ra khi một vận động viên rời khỏi khu vực thi đấu, và việc đó không phải do đối thủ gây ra."},
    183: {"en": "The minimum warning for running away, avoiding combat and/or time-wasting during ATO SHIBARAKU is HANSOKU CHUI.", "vi": "Cảnh cáo tối thiểu đối với việc chạy trốn, né tránh thi đấu và/hoặc câu giờ trong ATO SHIBARAKU là HANSOKU CHUI."},
    184: {"en": "The pivotal point of the throw must not be above the thrower's hip level and the opponent must be held onto throughout, so that a safe landing can be made.", "vi": "Điểm trục của đòn ném không được cao hơn mức hông của người ném và đối thủ phải được giữ trong suốt quá trình, để có thể tiếp đất an toàn."},
    185: {"en": "Holding the opponent's Karate Gi is not permitted to break a fall.", "vi": "Giữ võ phục Karate Gi của đối thủ không được phép để chống một cú ngã."},
    186: {"en": "KANSA does not need to interfere if the Referee gives a score for a technique done after the time is up.", "vi": "KANSA không cần can thiệp nếu trọng tài chính trao điểm cho một kỹ thuật được thực hiện sau khi hết giờ."},
    187: {"en": "YUKO is worth one point.", "vi": "YUKO có giá trị một điểm."},
    188: {"en": "WAZA-ARI is worth two points.", "vi": "WAZA-ARI có giá trị hai điểm."},
    189: {"en": "IPPON is worth three points.", "vi": "IPPON có giá trị ba điểm."},
    190: {"en": "It is the duty of the Tatami Manager to ensure before each bout or match that the Athletes are wearing the approved equipment.", "vi": "Quản lý thảm đấu có nghĩa vụ bảo đảm trước mỗi trận đấu hoặc trận đồng đội rằng các vận động viên đang mặc thiết bị đã được phê duyệt."},
    191: {"en": "WAZA-ARI is awarded for CHUDAN kicks.", "vi": "WAZA-ARI được trao cho các đòn đá CHUDAN."},
    192: {"en": "IPPON is awarded for JODAN kicks and any technique which is delivered on an opponent who has been thrown, has fallen on their own accord, or is otherwise off their feet.", "vi": "IPPON được trao cho các đòn đá JODAN và bất kỳ kỹ thuật nào được thực hiện lên một đối thủ đã bị ném, đã tự ngã, hoặc ở trạng thái không đứng trên chân theo cách khác."},
    193: {"en": "Individual bouts cannot be declared a tie.", "vi": "Các trận đấu cá nhân không thể được tuyên bố là hòa."},
    194: {"en": "Passivity can be given to any Athlete at any time.", "vi": "Tính thụ động có thể bị áp dụng cho bất kỳ vận động viên nào vào bất kỳ thời điểm nào."},
    195: {"en": "Passivity cannot be given during the first 15 seconds of a bout.", "vi": "Tính thụ động không thể bị áp dụng trong 15 giây đầu tiên của một trận đấu."},
    196: {"en": "Simulated attacks with the head, knees, or elbows are offenses.", "vi": "Các đòn tấn công giả vờ bằng đầu, đầu gối hoặc khuỷu tay là các vi phạm."},
    197: {"en": "Avoiding combat during the last 15 seconds of the bout (ATO SHIBARAKU) will as a minimum result in HANSOKU CHUI and loss of SENSHU.", "vi": "Né tránh thi đấu trong 15 giây cuối của trận đấu (ATO SHIBARAKU) sẽ, ở mức tối thiểu, dẫn đến HANSOKU CHUI và mất SENSHU."},
    198: {"en": "The Head Coach of a delegation can protest about a judgment to the members of the Referee Panel.", "vi": "Huấn luyện viên trưởng của một đoàn có thể khiếu nại về một phán xét lên các thành viên của Tổ trọng tài."},
    199: {"en": "Jacket ties must be tied.", "vi": "Các dây buộc của áo phải được buộc lại."},
    200: {"en": "At the beginning of a bout jackets without ties can be used.", "vi": "Ở đầu một trận đấu, các áo không có dây buộc có thể được sử dụng."},
    201: {"en": "In individual competition, an Athlete can be replaced by another after the draw has taken place.", "vi": "Trong thi đấu cá nhân, một vận động viên có thể được thay thế bởi một vận động viên khác sau khi việc bốc thăm đã diễn ra."},
    202: {"en": "At medal bouts, male Coaches are required to wear a dark suit, shirt, tie and shoes covering the toes.", "vi": "Tại các trận tranh huy chương, huấn luyện viên nam bắt buộc phải mặc bộ vest tối màu, áo sơ mi, cà vạt và giày che phủ các ngón chân."},
    203: {"en": "At medal bouts, female Coaches can choose to wear a dress, pantsuit or a combination of jacket and skirt in dark colours and shoes covering the toes.", "vi": "Tại các trận tranh huy chương, huấn luyện viên nữ có thể chọn mặc một chiếc váy liền, một bộ pantsuit hoặc kết hợp áo khoác và chân váy có màu tối và giày che phủ các ngón chân."},
    204: {"en": "At medal bouts, female Coaches cannot wear religious headwear.", "vi": "Tại các trận tranh huy chương, huấn luyện viên nữ không thể đeo khăn trùm đầu tôn giáo."},
    205: {"en": "An Athlete that refuses to follow the instructions of the Referee or displays a loss of temper will automatically receive HANSOKU.", "vi": "Một vận động viên từ chối tuân theo hướng dẫn của trọng tài chính hoặc thể hiện mất bình tĩnh sẽ tự động nhận HANSOKU."},
    206: {"en": "Athletes are not entitled to a period of time between bouts, equal to the standard duration time of the bout, for purpose of rest.", "vi": "Vận động viên không được hưởng một khoảng thời gian giữa các trận đấu, bằng thời lượng tiêu chuẩn của trận đấu, cho mục đích nghỉ ngơi."},
    207: {"en": "Passivity cannot be given after less than 15 seconds of bout time remaining.", "vi": "Tính thụ động không thể bị áp dụng sau khi trận đấu còn ít hơn 15 giây."},
    208: {"en": "Any excessive celebration, such as falling on one's knees etc., political, or religious expressions, during or immediately after the bout or match, are prohibited and can be subject to a fine equal to the protest fee determined by the Executive Committee.", "vi": "Bất kỳ hành vi ăn mừng quá mức nào, chẳng hạn như quỳ gối xuống, v.v., các biểu thị chính trị hoặc tôn giáo, trong hoặc ngay sau trận đấu hoặc trận đồng đội, đều bị cấm và có thể bị phạt tiền bằng phí khiếu nại do Ban Chấp hành quy định."},
    209: {"en": "If an Athlete receives KIKEN, or SHIKKAKU, in Round-robin competition all previous bouts are voided from the result.", "vi": "Nếu một vận động viên nhận KIKEN hoặc SHIKKAKU trong thi đấu vòng tròn, tất cả các trận đấu trước đó đều bị hủy bỏ khỏi kết quả."},
    210: {"en": "Grabbing the opponent's arm or Karate Gi with one hand is only allowed for attempting an immediate scoring technique or takedown.", "vi": "Việc nắm cánh tay hoặc võ phục Karate Gi của đối thủ bằng một tay chỉ được phép khi cố gắng thực hiện ngay một kỹ thuật ghi điểm hoặc một đòn quật ngã."},
    211: {"en": "Grabbing the opponent with both hands is never allowed during the bout.", "vi": "Việc nắm đối thủ bằng cả hai tay không bao giờ được phép trong trận đấu."},
    212: {"en": "It is the Tatami Manager's duty to appoint the video review Judge.", "vi": "Quản lý thảm đấu có nghĩa vụ chỉ định giám định xem lại video."},
    213: {"en": "If the number of IPPON and WAZA ARI is equal, the decision will be made by HANTEI.", "vi": "Nếu số lượng IPPON và WAZA-ARI bằng nhau, quyết định sẽ được đưa ra bằng HANTEI."},
    214: {"en": "In any individual bout, with equal score, and no SENSHU by either Athlete, the first criterion of the decision will be made based on the higher number of IPPON scored in the bout.", "vi": "Trong bất kỳ trận đấu cá nhân nào, với điểm số bằng nhau và không vận động viên nào có SENSHU, tiêu chí đầu tiên của quyết định sẽ dựa trên số lượng IPPON ghi được cao hơn trong trận đấu."},
    215: {"en": "If one Athlete has a score indicated by more than one Judge and the score is different between the Judges, the higher will be applied, unless there is majority for a lower score.", "vi": "Nếu một vận động viên có điểm được nhiều hơn một giám định chỉ ra và điểm số khác nhau giữa các giám định, điểm cao hơn sẽ được áp dụng, trừ khi có đa số cho một điểm số thấp hơn."},
    216: {"en": "The Tatami Manager must notify the central table if an Athlete has been stopped from further competition based on the 10-second rule.", "vi": "Quản lý thảm đấu phải thông báo cho bàn trung tâm nếu một vận động viên đã bị dừng không cho thi đấu tiếp dựa trên quy tắc 10 giây."},
    217: {"en": "The Timekeeper is responsible for starting the 3-minute count for an Athlete who is injured during a bout in progress and requires medical treatment.", "vi": "Người bấm giờ chịu trách nhiệm bắt đầu việc đếm 3 phút đối với một vận động viên bị chấn thương trong một trận đấu đang diễn ra và cần điều trị y tế."},
    218: {"en": "The Referee will not call YAME if an Athlete seizes the opponent and does not perform an immediate technique or throw.", "vi": "Trọng tài chính sẽ không hô YAME nếu một vận động viên túm giữ đối thủ và không thực hiện ngay một kỹ thuật hoặc một đòn ném."},
    219: {"en": "The Referee indicates the winner by hand signal and the order (AKA/AO NO KACHI), and by this action also resolves any tie.", "vi": "Trọng tài chính chỉ người chiến thắng bằng hiệu tay và hiệu lệnh (AKA/AO NO KACHI), và bằng hành động này cũng phân định mọi trường hợp hòa."},
    220: {"en": "If an Athlete seizes the opponent, the Referee will give several seconds for the Athlete to perform a throw or technique.", "vi": "Nếu một vận động viên túm giữ đối thủ, trọng tài chính sẽ cho vài giây để vận động viên thực hiện một đòn ném hoặc một kỹ thuật."},
    221: {"en": "The Coach or NF representative will request the official protest form from the Tatami Manager.", "vi": "Huấn luyện viên hoặc đại diện của Liên đoàn Quốc gia sẽ yêu cầu mẫu khiếu nại chính thức từ Quản lý thảm đấu."},
    222: {"en": "The Referee can stop the bout and give a point without the Judges' opinion.", "vi": "Trọng tài chính có thể dừng trận đấu và cho điểm mà không cần ý kiến của các giám định."},
    223: {"en": "If the Referee does not call the Doctor in a 10-second rule situation, KANSA must blow the whistle.", "vi": "Nếu trọng tài chính không gọi Bác sĩ trong tình huống quy tắc 10 giây, KANSA phải thổi còi."},
    224: {"en": "The winning team is the one with the most bout victories excluding those won by SENSHU.", "vi": "Đội chiến thắng là đội có nhiều trận thắng nhất, không kể các trận thắng bằng SENSHU."},
    225: {"en": "The red and blue belts must be no longer than three-quarters thigh length.", "vi": "Các đai đỏ và xanh phải không dài hơn ba phần tư chiều dài đùi."},
    226: {"en": "The correct penalty for feigning an injury if the Judges have determined that the technique in fact was a score, is HANSOKU.", "vi": "Hình phạt đúng đối với việc giả vờ chấn thương, nếu các giám định đã xác định rằng kỹ thuật trên thực tế là một điểm số, là HANSOKU."},
    227: {"en": "The information of officials implicated in the protest is completed by the Tatami Manager.", "vi": "Thông tin về các quan chức liên quan đến khiếu nại được Quản lý thảm đấu hoàn tất."},
    228: {"en": "Disqualification by KIKEN means that the Athlete is disqualified from that category, although it does not affect participation in another category.", "vi": "Truất quyền thi đấu bằng KIKEN có nghĩa là vận động viên bị truất quyền thi đấu khỏi hạng mục đó, mặc dù điều này không ảnh hưởng đến việc tham gia một hạng mục khác."},
    229: {"en": "Athletes are entitled to a rest period of time between bouts, equal to the standard duration time of the bout. The exception is in the case of change of equipment color, where this time is extended to five minutes.", "vi": "Vận động viên được hưởng một khoảng thời gian nghỉ giữa các trận đấu, bằng thời lượng tiêu chuẩn của trận đấu. Ngoại lệ là trường hợp thay đổi màu thiết bị, trong đó thời gian này được kéo dài thành năm phút."},
    230: {"en": "In any bout, if after full time the scores are equal, but one Athlete has obtained SENSHU, that Athlete will be declared the winner.", "vi": "Trong bất kỳ trận đấu nào, nếu sau khi hết thời gian thi đấu điểm số bằng nhau, nhưng một vận động viên đã giành được SENSHU, vận động viên đó sẽ được tuyên bố là người chiến thắng."},
    231: {"en": "By SENSHU is understood that one Athlete has achieved the first instance of scoring on the opponent without having the opponent also score before the signal.", "vi": "SENSHU được hiểu là một vận động viên đã đạt được trường hợp ghi điểm đầu tiên lên đối thủ mà đối thủ cũng không ghi điểm trước tín hiệu."},
    232: {"en": "In the event that an Athlete falls, is thrown, or knocked down and does not regain his or her feet immediately, the Referee will call the Doctor, and at the same time start a count to ten indicating his count showing a finger for each second.", "vi": "Trong trường hợp một vận động viên bị ngã, bị ném hoặc bị đánh ngã và không đứng dậy ngay lập tức, trọng tài chính sẽ gọi Bác sĩ, đồng thời bắt đầu đếm đến mười, thể hiện số đếm của mình bằng cách giơ một ngón tay cho mỗi giây."},
    233: {"en": "An audible signal will be given by the Timekeeper 15 seconds before the actual end of the bout and the Referee will announce \"ATO SHIBARAKU\".", "vi": "Một tín hiệu âm thanh sẽ được người bấm giờ đưa ra 15 giây trước khi trận đấu thực sự kết thúc và trọng tài chính sẽ tuyên bố “ATO SHIBARAKU”."},
    234: {"en": "KANSA must remain silent if the Referee gives a warning or penalty for passivity during ATO SHIBARAKU.", "vi": "KANSA phải giữ im lặng nếu trọng tài chính đưa ra cảnh cáo hoặc xử phạt vì tính thụ động trong ATO SHIBARAKU."},
    235: {"en": "In individual categories with elimination format, a bout can be declared a tie.", "vi": "Trong các hạng mục cá nhân với thể thức loại trực tiếp, một trận đấu có thể được tuyên bố là hòa."},
    236: {"en": "For all competition formats the Coach will be allowed one video review card for the Athlete.", "vi": "Đối với mọi thể thức thi đấu, huấn luyện viên sẽ được phép dùng một thẻ xem lại video cho vận động viên."},
    237: {"en": "The Athlete can ask the Coach to request a video review discreetely.", "vi": "Vận động viên có thể yêu cầu huấn luyện viên đề nghị xem lại video một cách kín đáo."},
    238: {"en": "The last six seconds before the bout was stopped for the request will always be evaluated for video review.", "vi": "Sáu giây cuối cùng trước khi trận đấu bị dừng cho yêu cầu đó sẽ luôn được đánh giá cho việc xem lại video."},
    239: {"en": "If both Coaches request video review at the same time, the video review Judge can only award the point to whoever is deemed to score first.", "vi": "Nếu cả hai huấn luyện viên cùng lúc yêu cầu xem lại video, giám định xem lại video chỉ có thể trao điểm cho người được coi là ghi điểm trước."},
    240: {"en": "Simultaneous scoring techniques can be awarded to both Athletes in video review.", "vi": "Các kỹ thuật ghi điểm đồng thời có thể được trao cho cả hai vận động viên trong xem lại video."},
    241: {"en": "The video review Judge cannot overrule any decision made by the Judges, with the exception of SENSHU.", "vi": "Giám định xem lại video không thể bác bỏ bất kỳ quyết định nào do các giám định đưa ra, ngoại trừ SENSHU."},
    242: {"en": "The Tatami Manager must supervise that KANSA stops the bout to instruct the Referee regarding a contravention of the Rules of Competition.", "vi": "Quản lý thảm đấu phải giám sát việc KANSA dừng trận đấu để hướng dẫn trọng tài chính về một vi phạm Quy định Thi đấu."},
    243: {"en": "The Referee indicates fouls observed, and imposes warnings and penalties as required by the Rules.", "vi": "Trọng tài chính chỉ ra các lỗi đã quan sát được và áp dụng các cảnh cáo và xử phạt theo yêu cầu của Luật."},
    244: {"en": "Referee breaks the tie in case of HANTEI.", "vi": "Trọng tài chính phân định trường hợp hòa trong trường hợp HANTEI."},
    245: {"en": "In the event that the Referee does not hear the time-up bell, KANSA will blow his whistle.", "vi": "Trong trường hợp trọng tài chính không nghe thấy chuông hết giờ, KANSA sẽ thổi còi của mình."},
    246: {"en": "In the Two Judges System, the Judges will assist the Referee by giving signals for JOGAI and excessive contact.", "vi": "Trong Hệ thống Hai Giám định, các giám định sẽ hỗ trợ trọng tài chính bằng cách đưa ra các tín hiệu cho JOGAI và va chạm quá mức."},
}

KATA_BILINGUAL: dict[int, dict[str, str]] = {
    1: {"en": "Kata team members must all wear the same brand of Karate Gi.", "vi": "Tất cả các thành viên của đội Kata đều phải mặc võ phục Karate Gi cùng một nhãn hiệu."},
    2: {"en": "The total time allowed for the Kata and BUNKAI demonstration combined is six minutes.", "vi": "Tổng thời gian cho phép cho phần biểu diễn Kata và Bunkai cộng lại là sáu phút."},
    3: {"en": "In Kata competition slight variations as taught by the contestant's style (Ryu-ha) are permitted.", "vi": "Trong thi đấu Kata, cho phép có những biến thể nhỏ như được dạy trong hệ phái (Ryu-ha) của vận động viên."},
    4: {"en": "Glasses are forbidden in Kata competition.", "vi": "Kính mắt bị cấm trong thi đấu Kata."},
    5: {"en": "Only one discreet rubber band on a single ponytail is permitted.", "vi": "Chỉ được phép dùng một dây thun kín đáo trên một đuôi tóc duy nhất."},
    6: {"en": "Kata competition can be organized in several formats.", "vi": "Thi đấu Kata có thể được tổ chức theo nhiều thể thức khác nhau."},
    7: {"en": "In all competition formats, the number of Athletes cannot exceed 8.", "vi": "Trong mọi thể thức thi đấu, số lượng vận động viên không được vượt quá 8."},
    8: {"en": "Team matches consist of competition between teams of 3 or 4 Athletes of which 3 compete at the time.", "vi": "Các trận đồng đội là cuộc tranh tài giữa các đội gồm 3 hoặc 4 vận động viên, trong đó 3 vận động viên thi đấu tại một thời điểm."},
    9: {"en": "Conformance is a consistency in the performance of the Kihon in the Kata.", "vi": "Sự phù hợp (Conformance) là sự nhất quán trong việc thực hiện Kihon trong bài Kata."},
    10: {"en": "Should there be any discrepancy between the number and the name of the Kata registered for performance, the name, as per the official WKF Kata list will prevail.", "vi": "Nếu có bất kỳ sự không thống nhất nào giữa số hiệu và tên của bài Kata đã đăng ký để biểu diễn, tên bài Kata theo danh sách Kata chính thức của WKF sẽ được lấy làm chuẩn."},
    11: {"en": "Giving a command to start and finish the Kata by a team member is not considered to be an external cue.", "vi": "Việc một thành viên của đội hô lệnh bắt đầu và kết thúc bài Kata không được coi là tín hiệu gợi ý từ bên ngoài."},
    12: {"en": "The mats must form a uniform coloured surface for Kata competition.", "vi": "Các thảm phải tạo thành một bề mặt có màu đồng nhất cho thi đấu Kata."},
    13: {"en": "Judges should look for correct Kihon of the Athlete's style (Ryu-ha) being demonstrated.", "vi": "Các giám định cần xem xét Kihon đúng của hệ phái (Ryu-ha) mà vận động viên đang thể hiện."},
    14: {"en": "The panel of Judges can be changed for any single round.", "vi": "Hội đồng giám định có thể được thay đổi cho bất kỳ vòng đấu riêng lẻ nào."},
    15: {"en": "The total time allowed for the Kata & BUNKAI demonstration combined, is 5 minutes.", "vi": "Tổng thời gian cho phép cho phần biểu diễn Kata và Bunkai cộng lại là 5 phút."},
    16: {"en": "In Kata competition the sleeves of the Karate Gi jacket cannot be rolled up.", "vi": "Trong thi đấu Kata, tay áo của áo võ phục Karate Gi không được xắn lên."},
    17: {"en": "It is the responsibility of the Coach or Athlete to notify the name and the number of the Kata to the runner prior to each round.", "vi": "Huấn luyện viên hoặc vận động viên có trách nhiệm thông báo tên và số hiệu của bài Kata cho người điều phối (runner) trước mỗi vòng đấu."},
    18: {"en": "The number of Judges per panel can be reduced to five for any competition.", "vi": "Số lượng giám định trong mỗi hội đồng có thể được giảm xuống còn năm người đối với bất kỳ giải đấu nào."},
    19: {"en": "A previously performed Kata can be repeated only if used as tiebreaker.", "vi": "Một bài Kata đã biểu diễn trước đó chỉ có thể được lặp lại nếu được dùng làm bài phân định thắng thua (tiebreaker)."},
    20: {"en": "The Karate Gi trousers can be slightly shorter so as to only cover half of the shin.", "vi": "Quần võ phục Karate Gi có thể ngắn hơn một chút sao cho chỉ che phủ một nửa ống chân."},
    21: {"en": "Incorrect Kiai is a foul.", "vi": "Kiai không đúng là một lỗi."},
    22: {"en": "In Para Karate if there are 3 or less Athletes a single Kata is performed to determine 1st through 3rd place.", "vi": "Trong Para Karate, nếu có từ 3 vận động viên trở xuống, một bài Kata duy nhất sẽ được biểu diễn để xác định các vị trí từ hạng nhất đến hạng ba."},
    23: {"en": "The Judges of a Kata bout cannot have the same nationality as either of the Athletes.", "vi": "Các giám định của một trận Kata không được có cùng quốc tịch với bất kỳ vận động viên nào trong hai vận động viên."},
    24: {"en": "Although ribbons and other decorations for the hair are not allowed in Kumite, they are permissible in Kata.", "vi": "Mặc dù ruy băng và các vật trang trí tóc khác không được phép trong Kumite, chúng được phép trong Kata."},
    25: {"en": "In the bouts for medals in Team Kata competition, teams will perform a demonstration of the meaning of the Kata (BUNKAI).", "vi": "Trong các trận tranh huy chương ở nội dung Kata đồng đội, các đội sẽ biểu diễn phần diễn giải ý nghĩa của bài Kata (Bunkai)."},
    26: {"en": "It is not possible to repeat a Kata in the Round-robin elimination system.", "vi": "Không thể lặp lại một bài Kata trong hệ thống loại trực tiếp kết hợp vòng tròn (Round-robin)."},
    27: {"en": "In all competitions formats, the number of Judges can be reduced to 3.", "vi": "Trong mọi thể thức thi đấu, số lượng giám định có thể được giảm xuống còn 3."},
    28: {"en": "Any Kata can be performed in the medal round, unless already performed twice.", "vi": "Bất kỳ bài Kata nào cũng có thể được biểu diễn ở vòng tranh huy chương, trừ khi bài đó đã được biểu diễn hai lần."},
    29: {"en": "If an already qualified individual Athlete or Team is disqualified for misconduct (SHIKKAKU) at the conclusion of the Round-robin phase, their scheduled opponent in the first round of the elimination phase shall advance to the next round by bye (“walkover”).", "vi": "Nếu một vận động viên cá nhân hoặc một đội đã giành quyền đi tiếp bị truất quyền thi đấu vì hành vi sai trái (SHIKKAKU) khi giai đoạn vòng tròn kết thúc, đối thủ theo lịch của họ ở vòng đầu tiên của giai đoạn loại trực tiếp sẽ được vào vòng tiếp theo mà không phải thi đấu (“walkover”)."},
    30: {"en": "Female Athletes must wear a plain white T-shirt beneath the Karate Gi jacket.", "vi": "Vận động viên nữ phải mặc áo thun trắng trơn bên trong áo võ phục Karate Gi."},
    31: {"en": "Female Athletes can, if they want, wear a plain white T-shirt beneath the Karate Gi jacket.", "vi": "Vận động viên nữ có thể mặc áo thun trắng trơn bên trong áo võ phục Karate Gi nếu họ muốn."},
    32: {"en": "The wearing of unauthorised apparel, clothing or equipment is forbidden.", "vi": "Việc mặc trang phục, quần áo hoặc sử dụng thiết bị không được phép là bị cấm."},
    33: {"en": "A discreet rubber band or ponytail retainer is permitted in Kata competition.", "vi": "Một dây thun kín đáo hoặc vật giữ đuôi tóc kín đáo được phép trong thi đấu Kata."},
    34: {"en": "The matted Kumite areas are not suitable for Kata competition.", "vi": "Các khu vực thảm của Kumite không phù hợp cho thi đấu Kata."},
    35: {"en": "The Karate Gi jacket can be removed during the performance of Kata.", "vi": "Áo võ phục Karate Gi có thể được cởi ra trong khi biểu diễn Kata."},
    36: {"en": "Any theatrics must be considered very serious fouls by the Judges – on the same level as one would penalize a major loss of balance.", "vi": "Mọi hành vi phô diễn, làm trò (theatrics) đều phải được các giám định coi là lỗi rất nghiêm trọng, ngang mức xử phạt đối với một lần mất thăng bằng nghiêm trọng."},
    37: {"en": "Variations as taught by the Athlete’s style (Ryu-ha) of Karate will not be permitted.", "vi": "Những biến thể như được dạy trong hệ phái Karate (Ryu-ha) của vận động viên sẽ không được phép."},
    38: {"en": "The runner must be notified of the choice of Kata prior to each round.", "vi": "Người điều phối (runner) phải được thông báo về bài Kata được chọn trước mỗi vòng đấu."},
    39: {"en": "A Team which does not perform the bow at the completion of the BUNKAI performance will be disqualified.", "vi": "Một đội không thực hiện động tác chào khi kết thúc phần biểu diễn Bunkai sẽ bị truất quyền thi đấu."},
    40: {"en": "The number of Kata required is dependent on the number of individual Athletes or Teams entered.", "vi": "Số lượng bài Kata yêu cầu phụ thuộc vào số lượng vận động viên cá nhân hoặc đội đã đăng ký tham gia."},
    41: {"en": "An Athlete who received SHIKKAKU can still be awarded a medal.", "vi": "Một vận động viên đã nhận SHIKKAKU vẫn có thể được trao huy chương."},
    42: {"en": "In assessing the performance of an Athlete or team the Judges will evaluate the performance based on all criteria.", "vi": "Khi đánh giá phần biểu diễn của một vận động viên hoặc một đội, các giám định sẽ đánh giá phần biểu diễn dựa trên tất cả các tiêu chí."},
    43: {"en": "There are no specific deviations for those under 14 years of age from the standard rules, but a limitation to the Kata list to less advanced Kata can be used.", "vi": "Không có quy định riêng biệt nào cho lứa tuổi dưới 14 tuổi khác với luật tiêu chuẩn, nhưng có thể áp dụng việc giới hạn danh sách Kata ở những bài Kata ít nâng cao hơn."},
    44: {"en": "Causing injury by lack of controlled technique during BUNKAI is considered a foul.", "vi": "Gây chấn thương do thiếu kiểm soát kỹ thuật trong khi thực hiện Bunkai được coi là một lỗi."},
    45: {"en": "For medal bouts, one of the Judges can have the same nationality as the Athletes.", "vi": "Đối với các trận tranh huy chương, một trong các giám định có thể có cùng quốc tịch với các vận động viên."},
    46: {"en": "Performances are given a score using a scale from 5.0 to 10.0 in increments of 0.1.", "vi": "Các phần biểu diễn được cho điểm theo thang điểm từ 5,0 đến 10,0 với bước tăng 0,1."},
    47: {"en": "A coin toss is the first choice to resolve ties.", "vi": "Tung đồng xu là lựa chọn đầu tiên để phân định trường hợp hòa."},
    48: {"en": "There are 6 criteria to resolve a tie in Round-robin elimination system with 4 Athletes.", "vi": "Có 6 tiêu chí để phân định trường hợp hòa trong hệ thống loại trực tiếp kết hợp vòng tròn với 4 vận động viên."},
    49: {"en": "Strength is one of the criteria of evaluation.", "vi": "Sức mạnh là một trong các tiêu chí đánh giá."},
    50: {"en": "There are 6 criteria to resolve a tie when having elimination system with 8 Athletes.", "vi": "Có 6 tiêu chí để phân định trường hợp hòa khi áp dụng hệ thống loại trực tiếp với 8 vận động viên."},
    51: {"en": "There are 10 criteria for Kata evaluation.", "vi": "Có 10 tiêu chí để đánh giá Kata."},
    52: {"en": "Transitional movement is one of the criteria for evaluation for Kata performance but not for BUNKAI.", "vi": "Động tác chuyển tiếp là một trong các tiêu chí đánh giá đối với phần biểu diễn Kata nhưng không phải đối với Bunkai."},
    53: {"en": "In BUNKAI performance, transitional movements and control are part of the evaluation.", "vi": "Trong phần biểu diễn Bunkai, các động tác chuyển tiếp và sự kiểm soát là một phần của việc đánh giá."},
    54: {"en": "Strength, speed and balance are some of the criteria of evaluation for Kata and BUNKAI.", "vi": "Sức mạnh, tốc độ và thăng bằng là một số tiêu chí đánh giá đối với Kata và Bunkai."},
    55: {"en": "Simulated unconsciousness for more than 2 seconds at the time as part of the BUNKAI is considered a foul.", "vi": "Giả vờ bất tỉnh trong hơn 2 giây tại thời điểm đó như một phần của Bunkai được coi là một lỗi."},
    56: {"en": "BUNKAI is to be given equal importance as the Kata itself.", "vi": "Bunkai phải được coi trọng ngang với chính bài Kata."},
    57: {"en": "Excessive bowing before starting the performance is considered a foul.", "vi": "Chào cúi đầu quá mức trước khi bắt đầu phần biểu diễn được coi là một lỗi."},
    58: {"en": "Causing injury by lack of controlled technique during BUNKAI is a disqualification.", "vi": "Gây chấn thương do thiếu kiểm soát kỹ thuật trong khi thực hiện Bunkai là một trường hợp truất quyền thi đấu."},
    59: {"en": "Not announcing the Kata is not considered as disqualification.", "vi": "Không hô tên bài Kata không được coi là trường hợp truất quyền thi đấu."},
    60: {"en": "Performing the wrong Kata or announcing the wrong Kata leads to disqualification.", "vi": "Biểu diễn sai bài Kata hoặc hô sai tên bài Kata dẫn đến truất quyền thi đấu."},
    61: {"en": "Stamping the feet, slapping the chest, arms, or Karate Gi, will be taken into account by the Judges when arriving at a decision.", "vi": "Dậm chân, vỗ vào ngực, cánh tay hoặc võ phục Karate Gi sẽ được các giám định xem xét khi đưa ra quyết định."},
    62: {"en": "An Athlete will not be disqualified for a distinct pause or stop in the performance for several seconds.", "vi": "Một vận động viên sẽ không bị truất quyền thi đấu vì một lần dừng hoặc ngừng rõ rệt trong phần biểu diễn kéo dài vài giây."},
    63: {"en": "BUNKAI is not to be given equal importance as the Kata itself.", "vi": "Bunkai không được coi trọng ngang với chính bài Kata."},
    64: {"en": "Kata must start facing the Judges.", "vi": "Bài Kata phải bắt đầu trong tư thế hướng mặt về phía các giám định."},
    65: {"en": "The use of audible cues from any other person, including other team members is considered a foul.", "vi": "Việc sử dụng tín hiệu bằng âm thanh từ bất kỳ người nào khác, kể cả các thành viên khác của đội, được coi là một lỗi."},
    66: {"en": "If the Athlete’s belt falls off during the performance of Kata, the Athlete will be disqualified.", "vi": "Nếu đai của vận động viên bị rơi ra trong khi biểu diễn Kata, vận động viên sẽ bị truất quyền thi đấu."},
    67: {"en": "Failure to follow the instructions of the Chief Judge or other misconduct is considered a foul.", "vi": "Không tuân theo hướng dẫn của Trưởng giám định hoặc có hành vi sai trái khác được coi là một lỗi."},
    68: {"en": "Failure to follow the instructions of the Chief Judge or other misconduct leads to disqualification.", "vi": "Không tuân theo hướng dẫn của Trưởng giám định hoặc có hành vi sai trái khác dẫn đến truất quyền thi đấu."},
    69: {"en": "Exceeding the total time limit of 5 minutes duration for Kata and BUNKAI is considered a foul.", "vi": "Vượt quá tổng giới hạn thời gian 5 phút cho Kata và Bunkai được coi là một lỗi."},
    70: {"en": "In Team Kata, all three team members must start and finish the Kata facing in the same direction and towards the Judges.", "vi": "Trong Kata đồng đội, cả ba thành viên của đội phải bắt đầu và kết thúc bài Kata hướng mặt về cùng một hướng và hướng về phía các giám định."},
    71: {"en": "Kata performance must be realistic in fighting terms and display concentration, power, and potential impact in its techniques.", "vi": "Phần biểu diễn Kata phải thực tế về mặt chiến đấu và thể hiện sự tập trung, sức mạnh và tác động tiềm tàng trong các kỹ thuật của nó."},
    72: {"en": "Causing injury by lack of controlled technique during BUNKAI is not considered a foul.", "vi": "Gây chấn thương do thiếu kiểm soát kỹ thuật trong khi thực hiện Bunkai không được coi là một lỗi."},
    73: {"en": "Minor loss of balance must not be considered in the evaluation of the Kata performance.", "vi": "Mất thăng bằng nhẹ không được xem xét trong việc đánh giá phần biểu diễn Kata."},
    74: {"en": "Exceeding the total time limit of 5 minutes duration for Kata and BUNKAI leads to disqualification.", "vi": "Vượt quá tổng giới hạn thời gian 5 phút cho Kata và Bunkai dẫn đến truất quyền thi đấu."},
    75: {"en": "Kata performance must demonstrate strength, balance, and speed.", "vi": "Phần biểu diễn Kata phải thể hiện sức mạnh, thăng bằng và tốc độ."},
    76: {"en": "Minor loss of balance must be considered in the evaluation of the Kata performance.", "vi": "Mất thăng bằng nhẹ phải được xem xét trong việc đánh giá phần biểu diễn Kata."},
    77: {"en": "Asynchronous movement, such as delivering a technique before the body transition is completed is considered a foul.", "vi": "Động tác không đồng bộ, chẳng hạn như thực hiện một kỹ thuật trước khi quá trình chuyển đổi cơ thể hoàn tất, được coi là một lỗi."},
    78: {"en": "Inappropriate exhalation will be taken into account by the Judges when arriving at a decision.", "vi": "Thở ra không phù hợp sẽ được các giám định xem xét khi đưa ra quyết định."},
    79: {"en": "In Team Kata, failing to do synchronised movements is not considered a foul.", "vi": "Trong Kata đồng đội, việc không thực hiện các động tác đồng bộ không được coi là một lỗi."},
    80: {"en": "Performing a movement in an incorrect or incomplete manner is considered a foul.", "vi": "Thực hiện một động tác theo cách không đúng hoặc không hoàn chỉnh được coi là một lỗi."},
    81: {"en": "Time wasting, including prolonged marching, excessive bowing or prolonged pause before starting the performance is considered a foul.", "vi": "Câu giờ, bao gồm diễu hành kéo dài, chào cúi đầu quá mức hoặc dừng kéo dài trước khi bắt đầu phần biểu diễn, được coi là một lỗi."},
    82: {"en": "Stamping the feet, slapping the chest, arms, or Karate Gi, are theatrics.", "vi": "Dậm chân, vỗ vào ngực, cánh tay hoặc võ phục Karate Gi là hành vi phô diễn, làm trò (theatrics)."},
    83: {"en": "The use of theatrics is not considered a foul.", "vi": "Việc sử dụng hành vi phô diễn, làm trò không được coi là một lỗi."},
    84: {"en": "Inappropriate exhalation is not considered theatrics.", "vi": "Thở ra không phù hợp không được coi là hành vi phô diễn, làm trò."},
    85: {"en": "Failure to fully execute a block or punching off target is considered a foul.", "vi": "Không thực hiện đầy đủ một động tác đỡ hoặc đấm trượt mục tiêu được coi là một lỗi."},
    86: {"en": "Causing injury by lack of controlled technique during BUNKAI is allowed.", "vi": "Gây chấn thương do thiếu kiểm soát kỹ thuật trong khi thực hiện Bunkai là được phép."},
    87: {"en": "The members of the team must demonstrate competence in all aspects of the Kata performance, as well as synchronisation.", "vi": "Các thành viên của đội phải thể hiện năng lực trong mọi khía cạnh của phần biểu diễn Kata, cũng như sự đồng bộ."},
    88: {"en": "Commands to start and stop the performance will be taken into account by the Judges when arriving at a decision.", "vi": "Các lệnh bắt đầu và dừng phần biểu diễn sẽ được các giám định xem xét khi đưa ra quyết định."},
    89: {"en": "It is the responsibility of the President of the National Federation to ensure that the Kata as notified to the runner is appropriate for that particular round.", "vi": "Chủ tịch Liên đoàn Quốc gia có trách nhiệm bảo đảm bài Kata đã thông báo cho người điều phối (runner) là phù hợp với vòng đấu cụ thể đó."},
    90: {"en": "While performing BUNKAI, after being downed the Athlete should either raise to one knee or stand up within 2 seconds.", "vi": "Trong khi biểu diễn Bunkai, sau khi bị quật ngã, vận động viên phải hoặc quỳ lên một đầu gối hoặc đứng dậy trong vòng 2 giây."},
    91: {"en": "Omitting or adding movements-or otherwise substantially change the performance from its original form is a disqualification.", "vi": "Bỏ bớt hoặc thêm động tác, hoặc thay đổi đáng kể phần biểu diễn so với hình thức gốc của nó theo cách khác, là một trường hợp truất quyền thi đấu."},
    92: {"en": "Excessive celebration and political or religious demonstrations is considered as disqualification for Kumite but not for Kata.", "vi": "Ăn mừng quá mức và các hành vi biểu thị chính trị hoặc tôn giáo được coi là trường hợp truất quyền thi đấu đối với Kumite nhưng không phải đối với Kata."},
    93: {"en": "Only Kata from the WKF official Kata list can be performed.", "vi": "Chỉ các bài Kata trong danh sách Kata chính thức của WKF mới có thể được biểu diễn."},
    94: {"en": "A team which does not perform the bow at the beginning and completion of the performance will be disqualified.", "vi": "Một đội không thực hiện động tác chào ở đầu và cuối phần biểu diễn sẽ bị truất quyền thi đấu."},
    95: {"en": "The use of traditional weapons, ancillary equipment or additional apparel is allowed.", "vi": "Việc sử dụng vũ khí truyền thống, thiết bị phụ trợ hoặc trang phục bổ sung là được phép."},
    96: {"en": "The performance in individual Kata is evaluated from the bow starting the Kata until the bow ending the Kata.", "vi": "Phần biểu diễn ở nội dung Kata cá nhân được đánh giá từ động tác chào bắt đầu bài Kata cho đến động tác chào kết thúc bài Kata."},
    97: {"en": "Belt coming loose to the extent that it is coming off the hips during the performance is a foul.", "vi": "Đai bị lỏng đến mức tuột khỏi hông trong khi biểu diễn là một lỗi."},
    98: {"en": "Belt coming loose to the extent that it is coming off the hips during the performance is a disqualification.", "vi": "Đai bị lỏng đến mức tuột khỏi hông trong khi biểu diễn là một trường hợp truất quyền thi đấu."},
    99: {"en": "After the bow the Athlete must clearly announce the name of the Kata that is to be performed and then start the performance.", "vi": "Sau động tác chào, vận động viên phải hô rõ tên bài Kata sẽ được biểu diễn và sau đó bắt đầu phần biểu diễn."},
    100: {"en": "There are 9 criteria in Kata evaluation.", "vi": "Có 9 tiêu chí trong việc đánh giá Kata."},
    101: {"en": "Although performing a scissor takedown technique (KANI BASAMI) to the neck area during BUNKAI is prohibited, a scissor takedown to the body is permitted.", "vi": "Mặc dù việc thực hiện kỹ thuật quật ngã bằng kéo (KANI BASAMI) vào vùng cổ trong khi thực hiện Bunkai là bị cấm, một đòn quật ngã bằng kéo vào thân người là được phép."},
    102: {"en": "Performing a scissor takedown technique (KANI BASAMI) to the neck area during BUNKAI is not prohibited.", "vi": "Việc thực hiện kỹ thuật quật ngã bằng kéo (KANI BASAMI) vào vùng cổ trong khi thực hiện Bunkai là không bị cấm."},
    103: {"en": "Theatrics must be considered very serious fouls by the Judges in their evaluation of the performance of the Kata.", "vi": "Hành vi phô diễn, làm trò phải được các giám định coi là lỗi rất nghiêm trọng trong đánh giá của họ về phần biểu diễn Kata."},
    104: {"en": "The protest can be submitted to a representative of the Appeals Jury by the Coach.", "vi": "Khiếu nại có thể được huấn luyện viên nộp cho một đại diện của Ban Phúc thẩm."},
    105: {"en": "It is the responsibility of the Tatami Manager receiving the protest to gather the Appeals Jury and deposit the protest sum with WKF for any declined protest.", "vi": "Quản lý thảm đấu tiếp nhận khiếu nại có trách nhiệm tập hợp Ban Phúc thẩm và nộp số tiền khiếu nại cho WKF đối với mọi khiếu nại bị bác bỏ."},
    106: {"en": "Each of the three members of the Appeals Jury is obliged to give their verdict as to the validity of the protest. Abstentions are not acceptable.", "vi": "Mỗi thành viên trong ba thành viên của Ban Phúc thẩm đều có nghĩa vụ đưa ra phán quyết của mình về tính hợp lệ của khiếu nại. Việc bỏ phiếu trắng là không được chấp nhận."},
    107: {"en": "In Para Karate, advertising on the backrest of the wheelchairs is allowed.", "vi": "Trong Para Karate, quảng cáo trên phần tựa lưng của xe lăn là được phép."},
    108: {"en": "If the protest is accepted, the Appeals Jury will appoint one of its members who will verbally notify the protester that the protest has been accepted.", "vi": "Nếu khiếu nại được chấp nhận, Ban Phúc thẩm sẽ chỉ định một thành viên của ban, người này sẽ thông báo bằng lời cho người khiếu nại rằng khiếu nại đã được chấp nhận."},
    109: {"en": "There are three general Categories in Para Karate competitions: Visually Impaired, Intellectually Impaired and Physically Impaired.", "vi": "Có ba hạng mục chung trong thi đấu Para Karate: Khiếm thị, Khuyết tật trí tuệ và Khuyết tật thể chất."},
    110: {"en": "In Para Karate competitions, prostheses, canes, crutches, and other equipment used for physical support are allowed.", "vi": "Trong thi đấu Para Karate, chân tay giả, gậy, nạng và các thiết bị khác dùng để hỗ trợ thể chất là được phép."},
    111: {"en": "In Para Karate, Athletes with more than one Eligible Impairment can compete in only one Sport Class per championship.", "vi": "Trong Para Karate, các vận động viên có nhiều hơn một dạng khuyết tật đủ điều kiện (Eligible Impairment) chỉ có thể thi đấu ở một Hạng thể thao (Sport Class) duy nhất trong mỗi giải vô địch."},
    112: {"en": "In Para Karate, the seven Judges will give their scores based on the assessment of the Kata performance and the level of the Athlete's impairment.", "vi": "Trong Para Karate, bảy giám định sẽ cho điểm dựa trên đánh giá phần biểu diễn Kata và mức độ khuyết tật của vận động viên."},
    113: {"en": "Para Karate competitions consist of both Kata and Kumite.", "vi": "Thi đấu Para Karate bao gồm cả Kata và Kumite."},
    114: {"en": "In Para Karate competitions wheelchairs with approved anti-tip castors are allowed.", "vi": "Trong thi đấu Para Karate, xe lăn có bánh chống lật đã được phê duyệt là được phép."},
    115: {"en": "In Para Karate a Compensation Score is allocated to Athletes in all Sport Classes in accordance with the WKF Para Karate Classification Rules.", "vi": "Trong Para Karate, Điểm bù (Compensation Score) được phân bổ cho các vận động viên ở mọi Hạng thể thao theo Quy định Phân loại Para Karate của WKF."},
    116: {"en": "In Para Karate, potential reasons for disqualification must be treated with particular care, as certain eligible impairments or underlying health conditions can influence movement patterns or behaviour during performance.", "vi": "Trong Para Karate, các lý do tiềm ẩn dẫn đến truất quyền thi đấu phải được xử lý đặc biệt thận trọng, vì một số dạng khuyết tật đủ điều kiện hoặc tình trạng sức khỏe nền nhất định có thể ảnh hưởng đến kiểu vận động hoặc hành vi trong khi biểu diễn."},
    117: {"en": "All Para Karate Athletes are allowed to wear white sport shoes.", "vi": "Tất cả các vận động viên Para Karate đều được phép mang giày thể thao màu trắng."},
    118: {"en": "In Para Karate, in case of additional Classification testing, Doping Control, fire or other need for emergency evacuation, the national Coaches are directly responsible for safe removal of their Athletes.", "vi": "Trong Para Karate, trong trường hợp cần kiểm tra Phân loại bổ sung, Kiểm tra Doping, hỏa hoạn hoặc nhu cầu sơ tán khẩn cấp khác, các huấn luyện viên quốc gia chịu trách nhiệm trực tiếp về việc đưa vận động viên của mình ra khỏi khu vực một cách an toàn."},
    119: {"en": "In Para Karate, Athletes from the Intellectually Impaired category can perform the same Kata in each round.", "vi": "Trong Para Karate, các vận động viên thuộc hạng mục Khuyết tật trí tuệ có thể biểu diễn cùng một bài Kata ở mỗi vòng."},
    120: {"en": "In Para Karate, service animals trained and certified to detect life-threatening conditions are not allowed at the external perimeter of the competition area.", "vi": "Trong Para Karate, động vật phục vụ đã được huấn luyện và chứng nhận để phát hiện các tình trạng đe dọa tính mạng không được phép ở vành đai bên ngoài của khu vực thi đấu."},
    121: {"en": "The Appeals Jury must elaborate a simple protest incident report, describing their findings and state their reason(s) for accepting or rejecting the protest.", "vi": "Ban Phúc thẩm phải lập một báo cáo sự việc khiếu nại đơn giản, mô tả các phát hiện của mình và nêu (các) lý do chấp nhận hoặc bác bỏ khiếu nại."},
    122: {"en": "There are 100 Kata on the official WKF Kata list.", "vi": "Có 100 bài Kata trong danh sách Kata chính thức của WKF."},
    123: {"en": "In Para Karate resolution for ties will follow the WKF Kata Competition Rules.", "vi": "Trong Para Karate, việc phân định trường hợp hòa sẽ tuân theo Quy định Thi đấu Kata của WKF."},
    124: {"en": "In Para Karate, therapy animals or emotional-support animals are allowed in the competition area or its perimeter.", "vi": "Trong Para Karate, động vật trị liệu hoặc động vật hỗ trợ tinh thần được phép ở trong khu vực thi đấu hoặc vành đai của khu vực đó."},
    125: {"en": "In Para Karate, it is allowed for Athletes of Visually Impaired Classes to wear blindfolds with logos or markings from sponsors or manufacturers.", "vi": "Trong Para Karate, các vận động viên thuộc các Hạng Khiếm thị được phép đeo bịt mắt có logo hoặc ký hiệu của nhà tài trợ hoặc nhà sản xuất."},
    126: {"en": "In Para Karate, the straps to fix the legs of wheelchair Athletes can be elastic.", "vi": "Trong Para Karate, các dây đai cố định chân của vận động viên sử dụng xe lăn có thể là dây thun co giãn."},
    127: {"en": "In Para Karate, score compensation system by means of Extra Points, must be given by the Judges according to the influence of the Athlete's particular impairment.", "vi": "Trong Para Karate, hệ thống bù điểm bằng Điểm cộng thêm (Extra Points) phải được các giám định áp dụng tùy theo ảnh hưởng của dạng khuyết tật cụ thể của vận động viên."},
    128: {"en": "In Para Karate there are three Sport Classes.", "vi": "Trong Para Karate có ba Hạng thể thao (Sport Class)."},
    129: {"en": "In Para Karate visually impaired Athletes are divided in three categories.", "vi": "Trong Para Karate, các vận động viên khiếm thị được chia thành ba hạng mục."},
    130: {"en": "In Para Karate, blindfolds are required for all visually impaired Athletes during the performance.", "vi": "Trong Para Karate, bịt mắt là bắt buộc đối với tất cả các vận động viên khiếm thị trong khi biểu diễn."},
    131: {"en": "In Para Karate, intellectual impaired Athletes will perform the Kata standing up.", "vi": "Trong Para Karate, các vận động viên khuyết tật trí tuệ sẽ biểu diễn Kata trong tư thế đứng."},
    132: {"en": "In Para Karate, intellectual impaired Athletes cannot repeat the Kata.", "vi": "Trong Para Karate, các vận động viên khuyết tật trí tuệ không thể lặp lại bài Kata."},
}
